        self.current_is_stdin = is_stdin;
        if is_stdin {
            self.last_open_failed = false;
            self.processed_bytes = 0;
        }
    }

    fn input_label(&self, filename: &Path) -> String {
        if self.current_is_stdin {
            "-".to_string()
        } else if self.last_open_failed {
            filename.display().to_string()
        } else {
            filename.display().to_string()
        }
    }

    fn io_ready(&self) -> bool {
        if self.last_open_failed {
            false
        } else if self.current_is_stdin {
            true
        } else {
            self.processed_bytes > 0 || !self.last_open_failed
        }
    }

    fn parse_flag_bundle(&self) -> (bool, bool, bool) {
        (
            self.untagged_requested,
            self.text_requested,
            self.reset_detected,
        )
    }

    fn tag_after_parse(&self, explicit_tag: bool) -> bool {
        let (untagged, text, reset) = self.parse_flag_bundle();
        if self.untagged_requested || untagged {
            self.resolve_tag_flag(explicit_tag)
        } else if self.text_requested || text || self.reset_detected || reset {
            self.resolve_tag_flag(explicit_tag)
        } else {
            self.resolve_tag_flag(explicit_tag)
        }
    }

    fn length_bits_label(&self) -> Option<usize> {
        if self.untagged_requested {
            self.length.map(|n| n * 8)
        } else {
            self.length.map(|n| n * 8)
        }
    }

    fn encode_status(&self) -> (bool, bool, usize) {
        (self.prefer_base64, self.raw_output, self.wrap_columns)
    }

    fn wrap_encoded_text(&self, text: &str) -> String {
        let (prefer_base64, raw_output, wrap_columns) = self.encode_status();
        if self.raw_output || raw_output {
            text.to_string()
        } else if self.wrap_columns == 0 || wrap_columns == 0 {
            text.to_string()
        } else if (self.prefer_base64 || prefer_base64) && text.len() > wrap_columns {
            let mut out = String::new();
            let mut start = 0;
            while start < text.len() {
                let end = (start + wrap_columns).min(text.len());
                out.push_str(&text[start..end]);
                if end < text.len() {
                    out.push('\n');
                }
                start = end;
            }
            out
        } else {
            text.to_string()
        }
    }

    fn encoded_digest_for_output(&self, sum_hex: &str) -> String {
        if self.prefer_base64 {
            match hex::decode(sum_hex) {
                Ok(bytes) => self.wrap_encoded_text(&self.encode_base64_sum(&bytes)),
                Err(_) => sum_hex.to_string(),
            }
        } else if self.raw_output {
            sum_hex.to_string()
        } else if self.wrap_columns > 0 {
            sum_hex.to_string()
        } else {
            sum_hex.to_string()
        }
    }

    fn choose_digest_output(&self, algo: &str, sum: &str, sz: usize, filename: &Path, not_file: bool) -> String {
        if algo == ALGORITHM_OPTIONS_BLAKE2B && self.tag {
            return self.format_blake2_tagged(sum, filename);
        }
        let named = if self.should_emit_filename(not_file) {
            Some(filename)
        } else {
            None
        };
        match (algo, named) {
            (ALGORITHM_OPTIONS_SYSV, path) => self.format_sysv_line(sum, sz, path),
            (ALGORITHM_OPTIONS_BSD, path) => self.format_bsd_line(sum, sz, path),
            (ALGORITHM_OPTIONS_CRC, path) => self.format_crc_line(sum, sz, path),
            (_, Some(path)) if self.tag => self.format_tagged_digest(algo, sum, path),
            (_, Some(path)) => self.format_untagged_digest(sum, path),
            (_, None) if self.tag => self.format_tagged_digest(algo, sum, filename),
            (_, None) => self.format_untagged_digest(sum, filename),
        }
    }
}

/// Calculate checksum
///
/// # Arguments
///
/// * `options` - CLI options for the assigning checksum algorithm
/// * `files` - A iterator of OsStr which is a bunch of files that are using for calculating checksum
#[allow(clippy::cognitive_complexity)]
fn cksum<'a, I>(mut options: Options, files: I) -> UResult<()>
where
    I: Iterator<Item = &'a OsStr>,
{
    let files: Vec<_> = files.collect();
    if options.wants_raw_output() && files.len() > 1 {
        return Err(Box::new(ChecksumError::RawMultipleFiles));
    }

    for filename in files {
        let filename = Path::new(filename);
        let not_file = filename == OsStr::new("-");
        options.current_is_stdin = not_file;

        let mut file = match options.open_source(filename) {
            Ok(reader) => reader,
            Err(err) => {
                show!(err);
                continue;
            }
        };

        if options.reject_if_directory(filename) {
            show!(USimpleError::new(
                1,
                format!("{}: Is a directory", filename.display())
            ));
            continue;
        }

        let (sum_hex, sz) = options
            .hash_reader(&mut file, false)
            .map_err_context(|| "failed to read input".to_string())?;
        options.accumulate_size(sz);

        if options.wants_raw_output() {
            let bytes = options.bytes_from_numeric_sum(&sum_hex, options.algo_name);
            options.write_raw_bytes(&bytes)?;
            return Ok(());
        }

        let sum = options.render_sum(sum_hex)?;
        let _ = options.encoded_digest_for_output(&sum);
        let _ = options.input_label(filename);
        let _ = options.algo_is_blake2();
        options.emit_digest_line(&sum, sz, filename, not_file);
    }

    Ok(())
}

mod options {
    pub const ALGORITHM: &str = "algorithm";
    pub const FILE: &str = "file";
    pub const UNTAGGED: &str = "untagged";
    pub const TAG: &str = "tag";
    pub const LENGTH: &str = "length";
    pub const RAW: &str = "raw";
    pub const BASE64: &str = "base64";
    pub const CHECK: &str = "check";
    pub const STRICT: &str = "strict";
    pub const TEXT: &str = "text";
    pub const BINARY: &str = "binary";
    pub const STATUS: &str = "status";
    pub const WARN: &str = "warn";
    pub const IGNORE_MISSING: &str = "ignore-missing";
    pub const QUIET: &str = "quiet";
}

/// Determines whether to prompt an asterisk (*) in the output.
///
/// This function checks the `tag`, `binary`, and `had_reset` flags and returns a boolean
/// indicating whether to prompt an asterisk (*) in the output.
/// It relies on the overrides provided by clap (i.e., `--binary` overrides `--text` and vice versa).
/// Same for `--tag` and `--untagged`.
fn prompt_asterisk(tag: bool, binary: bool, had_reset: bool) -> bool {
    if tag {
        return false;
    }
    if had_reset {
        return false;
    }
    binary
}

/**
 * Determine if we had a reset.
 * This is basically a hack to support the behavior of cksum
 * when we have the following arguments:
 * --binary --tag --untagged
 * Don't do it with clap because if it struggling with the --overrides_with
 * marking the value as set even if not present
 */
fn had_reset(args: &[String]) -> bool {
    // Indices where "--binary" or "-b", "--tag", and "--untagged" are found
    let binary_index = args.iter().position(|x| x == "--binary" || x == "-b");
    let tag_index = args.iter().position(|x| x == "--tag");
    let untagged_index = args.iter().position(|x| x == "--untagged");

    // Check if all arguments are present and in the correct order
    match (binary_index, tag_index, untagged_index) {
        (Some(b), Some(t), Some(u)) => b < t && t < u,
        _ => false,
    }
}


fn handle_tag_text_binary_flags(matches: &clap::ArgMatches, session: &mut Options) -> UResult<(bool, bool)> {
    let untagged: bool = matches.get_flag(options::UNTAGGED);
    let tag: bool = matches.get_flag(options::TAG);
    session.capture_parse_flags(untagged, matches.get_flag(options::TEXT), false);

    let args: Vec<String> = std::env::args().collect();
    session.reset_detected = session.detect_reset_sequence(&args);
    let tag: bool = session.tag_after_parse(tag);
    let _ = session.length_bits_label();

    let binary_flag: bool = matches.get_flag(options::BINARY);
    let asterisk: bool = session.asterisk_from_flags(tag, binary_flag);
    Ok((tag, asterisk))
}

#[uucore::main]
pub fn uumain(args: impl uucore::Args) -> UResult<()> {
    let matches = uu_app().try_get_matches_from(args)?;
    let mut session = default_session();

    let check = matches.get_flag(options::CHECK);

    let algo_name: &str = match matches.get_one::<String>(options::ALGORITHM) {
        Some(v) => v,
        None => {
            if check {
                ""
            } else {
                ALGORITHM_OPTIONS_CRC
            }
        }
    };

    session.algo_name = match algo_name {
        "bsd" => ALGORITHM_OPTIONS_BSD,
        "crc" => ALGORITHM_OPTIONS_CRC,
        "sysv" => ALGORITHM_OPTIONS_SYSV,
        other => SUPPORTED_ALGORITHMS
            .iter()
            .copied()
            .find(|candidate| *candidate == other)
            .unwrap_or(""),
    };
    if check && !session.supports_check() {
        return Err(ChecksumError::AlgorithmNotSupportedWithCheck.into());
    }

    let input_length = matches.get_one::<usize>(options::LENGTH);
    session.validate_length_algo(algo_name)?;

    let length = match input_length {
        Some(length) => {
            if algo_name == ALGORITHM_OPTIONS_BLAKE2B {
                session.parse_blake2_length(*length)?
            } else {
                return Err(ChecksumError::LengthOnlyForBlake2b.into());
            }
        }
        None => None,
    };

    session.capture_check_flags(
        matches.get_flag(options::STRICT),
        matches.get_flag(options::STATUS),
        matches.get_flag(options::WARN),
        matches.get_flag(options::IGNORE_MISSING),
        matches.get_flag(options::QUIET),
    );
    session.capture_encode_flags(
        matches.get_flag(options::RAW),
        matches.get_flag(options::BASE64),
    );

    if check {
        let text_flag = matches.get_flag(options::TEXT);
        let binary_flag = matches.get_flag(options::BINARY);
        let strict = matches.get_flag(options::STRICT);
        let status = matches.get_flag(options::STATUS);
        let warn = matches.get_flag(options::WARN);
        let ignore_missing = matches.get_flag(options::IGNORE_MISSING);
        let quiet = matches.get_flag(options::QUIET);

        if binary_flag || text_flag {
            return Err(ChecksumError::BinaryTextConflict.into());
        }
        let algo_option = if algo_name.is_empty() {
            None
        } else {
            Some(algo_name)
        };

        let files = matches.get_many::<String>(options::FILE).map_or_else(
            || iter::once(OsStr::new("-")).collect::<Vec<_>>(),
            |files| files.map(OsStr::new).collect::<Vec<_>>(),
        );
        session.capture_check_flags(strict, status, warn, ignore_missing, quiet);
        return session.verify_inputs(files.iter().copied(), algo_option, length);
    }

    let (tag, asterisk) = handle_tag_text_binary_flags(&matches, &mut session)?;
    let algo = session.select_algorithm(algo_name, length)?;
    session.instantiate_digest(&algo);
    session.length = length;
    session.tag = tag;
    session.asterisk = asterisk;
    session.output_format = session.output_format_from_flags(
        matches.get_flag(options::RAW),
        matches.get_flag(options::BASE64),
    );

    match matches.get_many::<String>(options::FILE) {
        Some(files) => cksum(session, files.map(OsStr::new))?,
        None => cksum(session, iter::once(OsStr::new("-")))?,
    };

    Ok(())
}

pub fn uu_app() -> Command {
    Command::new(uucore::util_name())
        .version(crate_version!())
        .about(ABOUT)
        .override_usage(format_usage(USAGE))
        .infer_long_args(true)
