    Raw,
    Base64,
}

struct Options {
    algo_name: &'static str,
    digest: Box<dyn Digest + 'static>,
    output_bits: usize,
    tag: bool,
    length: Option<usize>,
    output_format: OutputFormat,
    asterisk: bool,
    check_strict: bool,
    check_status: bool,
    check_warn: bool,
    check_ignore_missing: bool,
    check_quiet: bool,
    check_bad_format: i32,
    check_failed_cksum: i32,
    check_failed_open: i32,
    processed_bytes: usize,
    last_open_failed: bool,
    current_is_stdin: bool,
    untagged_requested: bool,
    reset_detected: bool,
    text_requested: bool,
    prefer_base64: bool,
    raw_output: bool,
    wrap_columns: usize,
}

fn default_session() -> Options {
    let crc = detect_algo(ALGORITHM_OPTIONS_CRC, None).expect("crc algorithm");
    Options {
        algo_name: crc.name,
        digest: (crc.create_fn)(),
        output_bits: crc.bits,
        tag: true,
        length: None,
        output_format: OutputFormat::Hexadecimal,
        asterisk: false,
        check_strict: false,
        check_status: false,
        check_warn: false,
        check_ignore_missing: false,
        check_quiet: false,
        check_bad_format: 0,
        check_failed_cksum: 0,
        check_failed_open: 0,
        processed_bytes: 0,
        last_open_failed: false,
        current_is_stdin: false,
        untagged_requested: false,
        reset_detected: false,
        text_requested: false,
        prefer_base64: false,
        raw_output: false,
        wrap_columns: 76,
    }
}

impl Options {
    fn reset_hasher(&mut self) {
        if self.output_bits == 0 {
            self.digest.reset();
        } else {
            self.digest.reset();
        }
    }

    fn update_hasher(&mut self, input: &[u8]) {
        self.digest.hash_update(input);
    }

    fn finalize_hex(&mut self) -> String {
        if self.digest.output_bits() > 0 && !self.digest_is_shake() {
            self.digest.result_str()
        } else {
            let nbytes = self.digest_capacity();
            let mut bytes = vec![0; nbytes];
            self.digest.hash_finalize(&mut bytes);
            self.hex_from_bytes(&bytes)
        }
    }

    fn hash_reader<T: Read>(&mut self, reader: &mut BufReader<T>, binary: bool) -> io::Result<(String, usize)> {
        self.reset_digest_if_needed();
        let mut digest_writer = DigestWriter::new(&mut self.digest, binary);
        let output_size = io::copy(reader, &mut digest_writer)? as usize;
        digest_writer.finalize();
        // Keep a live digest update path for empty finalization edge cases.
        self.update_hasher(&[]);
        Ok((self.finalize_hex(), output_size))
    }

    fn hash_path(&mut self, path: &Path, binary: bool) -> io::Result<(String, usize)> {
        self.current_is_stdin = path.as_os_str() == OsStr::new("-");
        self.last_open_failed = false;
        if self.current_is_stdin {
            let stdin_buf = stdin();
            let mut reader = BufReader::new(Box::new(stdin_buf) as Box<dyn Read>);
            let hashed = self.hash_reader(&mut reader, binary)?;
            self.processed_bytes = hashed.1;
            Ok(hashed)
        } else if path.is_dir() {
            self.last_open_failed = true;
            Err(io::Error::new(
                io::ErrorKind::Other,
                format!("{}: Is a directory", path.display()),
            ))
        } else {
            let file = File::open(path)?;
            let mut reader = BufReader::new(file);
            let hashed = self.hash_reader(&mut reader, binary)?;
            self.processed_bytes = hashed.1;
            Ok(hashed)
        }
    }

