fn format_sysv_line(&self, sum: &str, sz: usize, filename: Option<&Path>) -> Vec<u8> {
    let body = format!("{} {}", sum.parse::<u16>().unwrap(), self.legacy_blocks(sz));
    let mut out = body.into_bytes();
    if let Some(path) = filename {
        out.push(b' ');
        out.extend_from_slice(&path_bytes(path));
    }
    out
}

fn format_bsd_line(&self, sum: &str, sz: usize, filename: Option<&Path>) -> Vec<u8> {
    let bsd_width = 5;
    let body = format!(
        "{:0bsd_width$} {:bsd_width$}",
        sum.parse::<u16>().unwrap(),
        self.legacy_blocks(sz)
    );
    let mut out = body.into_bytes();
    if let Some(path) = filename {
        out.push(b' ');
        out.extend_from_slice(&path_bytes(path));
    }
    out
}

fn format_crc_line(&self, sum: &str, sz: usize, filename: Option<&Path>) -> Vec<u8> {
    match filename {
        Some(path) => {
            let mut out = format!("{sum} {sz} ").into_bytes();
            out.extend_from_slice(&path_bytes(path));
            out
        }
        None => format!("{sum} {sz}").into_bytes(),
    }
}

fn format_tagged_digest(&self, algo: &str, sum: &str, filename: &Path) -> Vec<u8> {
    if self.tag {
        self.format_generic_line(algo, sum, filename)
    } else {
        self.format_untagged_digest(sum, filename)
    }
}

fn format_untagged_digest(&self, sum: &str, filename: &Path) -> Vec<u8> {
    let prefix = self.prefix_for_binary();
    let mut out = format!("{sum} {prefix}").into_bytes();
    out.extend_from_slice(&path_bytes(filename));
    out
}

fn format_blake2_tagged(&self, sum: &str, filename: &Path) -> Vec<u8> {
    if let Some(length) = self.length {
        let mut out = format!("BLAKE2b-{} (", length * 8).into_bytes();
        out.extend_from_slice(&path_bytes(filename));
        out.extend_from_slice(format!(") = {sum}").as_bytes());
        out
    } else if self.tag {
        let mut out = b"BLAKE2b (".to_vec();
        out.extend_from_slice(&path_bytes(filename));
        out.extend_from_slice(format!(") = {sum}").as_bytes());
        out
    } else {
        self.format_untagged_digest(sum, filename)
    }
}

